import requests

def get_planets():
    url = 'https://api.axiverse.com/planets'
    resp = requests.get(url)
    return resp.json()

def get_planets_desc():
    planets = get_planets()
    result = {}
    for p in planets:
        url = f'https://api.axiverse.com/planets/{p}'
        resp = requests.get(url)
        desc = resp.json()
        result[p] = desc
    return result

