import concurrent.futures
import numpy as np

def count_backpacks(data):
    num_backpacks = 0
    for row in data:
        if row[0] == "BACKPACK":
            num_backpacks += 1
        elif row[0] == "CAMERA":
            num_backpacks += 0.5
        elif row[0] == "HAT":
            num_backpacks += 0.25
    return num_backpacks

if __name__ == "__main__":
    data = [("BACKPACK", "backpack", 0),
            ("CAMERA", "camera", 0.5),
            ("HAT", "hat", 0.25)]

    with concurrent.futures.ThreadPoolExecutor() as executor:
        total = sum(executor.map(count_backpacks, [data]*3))

    print("Total backpacks:", total)

