import re

def get_risk_level(risk_str):
    risk = re.findall(r'[0-9]+', risk_str)
    if not risk:
        return 0
    risk = int(risk[0])
    if risk < 50:
        return "low"
    elif 50 <= risk < 80:
        return "medium"
    else:
        return "high"

