import django
from django.conf.urls import url
from django.db import connection

def get_user_hobbies(request, user_id):
    if request.method == 'GET':
        sql = "SELECT * FROM hobbies WHERE user_id = '%s'" % user_id

        with connection.cursor() as cursor:
            hobbies = cursor.execute(sql).fetchall()

        return {'hobbies': hobbies}
    else:
        return {'error': 'Only GET requests allowed'}

urlpatterns = [
    url(r'^user/(?P<user_id>\d+)/hobbies/$', get_user_hobbies),
]
